function trace() {
  const box = document.getElementById("traceBox");
  const pts = D.winprob;
  const W = 1000, H = 190, mL = 34, mR = 10, mT = 10, mB = 20;
  const iw = W - mL - mR, ih = H - mT - mB;
  const X = i => mL + (i / (pts.length - 1)) * iw;
  const Y = v => mT + (1 - v) * ih;
  document.getElementById("traceHdr").textContent =
    `Win probability, Baylor, all ${pts.length - 1} plays`;
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img",
    "aria-label": "Baylor win probability across the game" }, box);

  // ruled chart paper behind the trace
  for (let v = 0; v <= 1.0001; v += .25) {
    el("line", { x1: mL, x2: W - mR, y1: Y(v), y2: Y(v),
      stroke: v === .5 ? C("--rule") : C("--rule-hair"),
      "stroke-width": v === .5 ? 1 : .75,
      "stroke-dasharray": v === .5 ? "4 3" : "none" }, svg);
    const t = el("text", { x: mL - 6, y: Y(v) + 3, "text-anchor": "end",
      "font-family": C("--mono"), "font-size": 8, fill: C("--ink-3") }, svg);
    t.textContent = Math.round(v * 100) + "%";
  }
  // No quarter rules: the win-probability feed carries no period or clock field, so
  // quarter boundaries cannot be derived. Plays are not evenly distributed across
  // quarters, so an evenly-spaced rule would be a fabricated axis. The x-axis is the
  // play sequence and is labelled as such.
  let d = "";
  pts.forEach((p, i) => { d += (i ? "L" : "M") + X(i).toFixed(1) + " " + Y(p.wp).toFixed(1); });
  el("path", { d, fill: "none", stroke: C("--obs"), "stroke-width": 1.6,
    "stroke-linejoin": "round" }, svg);

  // scoring events ticked on the trace and numbered to the table below
  D.score_events.forEach((e, n) => {
    const i = pts.findIndex(p => p.p === e.p);
    if (i < 0) return;
    const x = X(i), y = Y(e.wp);
    el("line", { x1: x, x2: x, y1: mT + ih, y2: y, stroke: C("--ink-3"),
      "stroke-width": .75, "stroke-dasharray": "2 2" }, svg);
    el("circle", { cx: x, cy: y, r: 3, fill: C("--paper"), stroke: C("--ink"),
      "stroke-width": 1.2 }, svg);
    const t = el("text", { x, y: mT + ih + 13, "text-anchor": "middle",
      "font-family": C("--mono"), "font-size": 7.5, fill: C("--ink-2") }, svg);
    t.textContent = n + 1;
  });
  const lastT = el("text", { x: W - mR, y: Y(1) + 9, "text-anchor": "end",
    "font-family": C("--mono"), "font-size": 8, fill: C("--ink-2") }, svg);
  lastT.textContent = `FINAL ${M.team_score}–${M.opp_score}`;
  const axT = el("text", { x: mL, y: H - 6, "font-family": C("--mono"),
    "font-size": 8, fill: C("--ink-3") }, svg);
  axT.textContent = `PLAY 1 → ${pts.length - 1}`;

  document.getElementById("traceLegend").innerHTML =
    `<span>${markObs(9)} Baylor win probability</span>` +
    `<span><svg width="11" height="11" viewBox="0 0 12 12" aria-hidden="true">
       <circle cx="6" cy="6" r="3.6" fill="${C("--paper")}" stroke="${C("--ink")}" stroke-width="1.4"/></svg>
       Scoring play, numbered below</span>` +
    `<span>Horizontal axis is play sequence, not clock time</span>`;

  // swing colour is direction, not magnitude: blue when it moved toward Baylor,
  // oxide when it moved away. Magnitude is carried by the number itself.
  document.getElementById("eventRows").innerHTML = D.score_events.map((e, n) => `
    <tr>
      <td>${n + 1}</td>
      <td class="lbl clip">${esc(e.text)}</td>
      <td class="r">${e.hs}–${e.as}</td>
      <td class="r">${Math.round(e.wp * 100)}%</td>
      <td class="r ${e.swing >= 0 ? "gain" : "loss"}">${signed(e.swing * 100, 0)} pts</td>
    </tr>`).join("");
})();

